/**
 * Embedded Futrus - Two Kings.pnc Demo Dataset
 * Pre-loaded binary base64 for instant 1-click testing
 */
export const FUTRUS_PNC_BASE64 = "";

export function getFutrusPncUint8Array() {
  const binStr = atob(FUTRUS_PNC_BASE64);
  const len = binStr.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binStr.charCodeAt(i);
  }
  return bytes;
}
